using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace OneMoreTime.EditorTools {
public static class SceneValidator {
 static bool IsDefault<T>(T value)=>System.Collections.Generic.EqualityComparer<T>.Default.Equals(value,default);
 public static void Validate(){var report=new StringBuilder();var prev=SceneManager.GetActiveScene();foreach(string name in SceneFlow.Scenes){string path=DemoBuilder.Root+"/Scenes/"+name+".unity";var scene=SceneManager.GetSceneByPath(path);bool opened=!scene.IsValid()||!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Additive);var roots=scene.GetRootGameObjects();var components=roots.SelectMany(r=>r.GetComponentsInChildren<Component>(true)).ToArray();int missing=components.Count(c=>c==null);if(missing>0)throw new Exception(name+" missing scripts "+missing);int players=components.Count(c=>c is PlayerMotor2D),cameras=components.Count(c=>c is Camera),echoes=components.Count(c=>c is EchoSurface);bool level=name.StartsWith("L0");if(cameras!=1||players!=(level?1:0)||echoes!=(level?1:0))throw new Exception(name+" duplicate/missing actors");
 foreach(var run in components.OfType<RunManager>()){if(run.config==null||run.player==null||run.visual==null||run.echo==null||run.view==null||run.uiFont==null||run.path==null)throw new Exception(name+" required reference missing");for(int i=0;i<run.config.doors.Length;i++)if(run.config.DoorSource(i)<0||run.config.DoorSource(i)>=run.config.plates.Length)throw new Exception("Door mapping mismatch");var door=run.transform.Find("Goal").GetComponent<SpriteRenderer>();float gap=door.bounds.min.y-run.config.goal.yMin;if(Mathf.Abs(gap)>.001f)throw new Exception(name+" floating exit door: "+gap);var landscape=run.transform.Find("Continuous landscape");if(landscape==null)throw new Exception(name+" missing continuous landscape");
 var landscapeSprite=landscape.GetComponent<SpriteRenderer>().sprite;
 var cfg=run.config;float expectedWidth=(Mathf.Ceil(cfg.terrain.Max(r=>r.xMax)*16)-Mathf.Floor(cfg.terrain.Min(r=>r.xMin)*16))/16;
 float expectedHeight=(Mathf.Ceil(cfg.terrain.Max(r=>r.yMax)*16)-Mathf.Floor(cfg.terrain.Min(r=>r.yMin)*16))/16;
 if(landscapeSprite==null||Mathf.Abs(landscapeSprite.bounds.size.x-expectedWidth)>.001f||Mathf.Abs(landscapeSprite.bounds.size.y-expectedHeight)>.001f)throw new Exception(name+" landscape sprite truncates configured terrain");
 report.AppendLine($"{name}: landscapeSize={landscapeSprite.bounds.size}; crop={landscapeSprite.rect}; fullTerrainCoverage=PASS");report.AppendLine($"{name}: exitGroundGap={gap:F6}; continuousLandscape=PASS");}
 foreach(var menu in components.OfType<MenuScreen>())if(menu.dialogueFrame==null||menu.goatPortrait==null)throw new Exception(name+" missing opening story artwork");
 foreach(var e in components.OfType<EchoSurface>())if(e.GetComponentsInChildren<PlayerMotor2D>().Length!=0||e.GetComponentsInChildren<Rigidbody2D>().Length!=0)throw new Exception("Echo contains live motor");
 foreach(var component in components.Where(c=>c is MonoBehaviour)){var serialized=new SerializedObject(component);var it=serialized.GetIterator();while(it.NextVisible(true)){if(it.propertyType==SerializedPropertyType.ObjectReference&&!IsDefault(it.objectReferenceEntityIdValue)&&it.objectReferenceValue==null)throw new Exception(name+" broken reference "+it.propertyPath);}}
 report.AppendLine($"{name}: objects={components.OfType<Transform>().Count()} players={players} cameras={cameras} echoes={echoes} plates={components.OfType<PressurePlate>().Count()} doors={components.OfType<LinkedDoor>().Count()} missingScripts={missing}");if(opened)EditorSceneManager.CloseScene(scene,true);}
 SceneManager.SetActiveScene(prev);File.WriteAllText("Artifacts/Logs/scene-validation.txt",report.ToString());
 var font=PresentationBuilder.Font;string all=string.Join("",Directory.GetFiles(DemoBuilder.Root+"/Runtime","*.cs").Select(File.ReadAllText));var missingChars=all.Where(c=>c>127&&!font.HasCharacter(c)).Distinct().ToArray();File.WriteAllText("Artifacts/Logs/font-validation.txt","Font="+font.name+"; missingCJK="+new string(missingChars));if(missingChars.Length>0)throw new Exception("Missing CJK glyphs: "+new string(missingChars));
 }
}
}
